{"id": "gen-modal-01", "task": "generation", "prompt": "Build a settings modal with a title, two text inputs, a cancel button and a save button, with an enter animation.", "must_match": ["prefers-reduced-motion", "scale\\(0\\.9[0-9]?\\)|scale: ?0\\.9"], "must_not_match": ["transition: ?all", "scale\\(0\\)", "ease-in[^-]"], "checklist_rows": [1, 2, 3, 6]}
