{"id": "gen-send-sound-01", "task": "generation", "prompt": "Add a confirmation sound when a chat message sends, with a settings toggle.", "must_match": ["resume\\(\\)|user gesture|pointerdown|click", "localStorage|persist"], "must_not_match": ["mouseenter", "autoplay", "^\\s*(const|let|var)\\s+\\w+\\s*=\\s*new AudioContext\\(\\);?\\s*$"], "checklist_rows": [12, 13]}
{"id": "edit-hover-01", "task": "edit", "instruction": "Make the card lift on hover.", "input": ".card { transition: all 0.3s ease-in; }\n.card:hover { transform: translateY(-4px); box-shadow: 0 16px 32px rgba(0,0,0,0.3); }", "must_match": ["transition: ?(transform|box-shadow)", "hover: ?hover"], "must_not_match": ["transition: ?all", "translateY\\(-4px\\)", "ease-in[^-]"], "checklist_rows": [1, 3, 7, 8]}
