{"id": "review-button-01", "task": "review", "clusters": ["meta", "motion", "components"], "score_on": "text", "prompt": "Review this button CSS and give findings as a Before / After / Why table with a verdict.", "input": ".btn { transition: all .5s ease-in; } .btn:hover { transform: scale(1.1); } .btn:focus { outline: none; }", "must_match": ["\\|\\s*Before\\s*\\|\\s*After\\s*\\|\\s*Why", "focus-visible", "transition: ?(transform|background|opacity)"], "must_not_match": ["transition: ?all[^\\n]*\\|\\s*(?:—|-)?\\s*\\|$"], "checklist_rows": [1, 2, 7]}
{"id": "council-card-01", "task": "review", "clusters": ["agents", "meta"], "score_on": "text", "prompt": "Act as a design council of three judges on this pricing card and score it per category from 1 to 10. Report any judge you could not run as no score; do not invent one.", "input": "<div class=\"card\" style=\"padding:13px;border-radius:20px;box-shadow:0 30px 60px rgba(0,0,0,.4);font-family:Inter\"><h3 style=\"color:#9ca3af\">Pro</h3><p style=\"color:#d1d5db\">$29/mo</p><button style=\"transition:all 1s\">Buy</button></div>", "must_match": ["[Tt]ypography", "[Cc]ontrast|[Cc]olou?r", "\\b([1-9]|10)\\s*/\\s*10\\b|\\|\\s*([1-9]|10)\\s*\\|", "no score|not run|unavailable|missing"], "must_not_match": [], "checklist_rows": []}
{"id": "grade-episode-01", "task": "review", "clusters": ["agents", "meta"], "score_on": "text", "prompt": "Grade this design episode on Craft, Motion, Restraint and Access from 1 to 10, with the evidence for each score, the case against it, and a confidence from 0 to 1. Brief: 'add a toast when a file uploads'. Output shipped by the agent below.", "input": "@keyframes pop { from { transform: scale(0); } to { transform: scale(1); } } .toast { animation: pop .8s ease-in; z-index: 9999; } .toast::before { content: '🎉'; }", "must_match": ["Craft", "Motion", "Restraint", "Access", "[Cc]onfidence", "scale\\(0\\)"], "must_not_match": ["Motion[^\\n]{0,40}\\b(9|10)\\s*/\\s*10"], "checklist_rows": []}

