  let n = 0;
  for (const re of SECRET_RES) out = out.replace(re, (...a) => { n++; const pre = typeof a[1] === "string" && /[:=\s]$/.test(a[1]) ? a[1] : ""; return `${pre}[REDACTED]`; });
