const args = process.argv.slice(2);
const dir = args.find((a) => !a.startsWith("--"));
if (!dir) {
  console.error("usage: node svg-flipbook.mjs <frames-dir> [--fps 12] [--out file.svg] [--name id] [--no-loop] [--vars] [--title text]");
  process.exit(1);
}
